  if (
    typeof DATA === 'undefined' ||
    !Array.isArray(DATA.questions) ||
    !Array.isArray(DATA.entities) ||
    !Array.isArray(DATA.axes)
  ) return;

  const questionIndexes = new Map(
    DATA.questions.map((question, index) => [question.id, index])
  );
  const entitiesById = new Map(DATA.entities.map(entity => [entity.id, entity]));
  const touchedEntities = new Set();

  Object.entries(CONSOLIDATED_OVERRIDES.questions).forEach(([questionId, override]) => {
    const questionIndex = questionIndexes.get(Number(questionId));
    if (questionIndex === undefined) return;

    if (override.question) {
      DATA.questions[questionIndex] = {
        ...override.question,
        coefficients: { ...override.question.coefficients }
      };
    }

    Object.entries(override.entities || {}).forEach(([entityId, entityOverride]) => {
      const entity = entitiesById.get(entityId);
      if (!entity) return;

      entity.responses[questionIndex] = entityOverride.response;
      entity.confidence[questionIndex] = entityOverride.confidence;
      entity.justifications[questionIndex] = entityOverride.justification;
      entity.sources[questionIndex] = entityOverride.source;
      touchedEntities.add(entity);
    });
  });

  touchedEntities.forEach(entity => {
    entity.axisScores = Object.fromEntries(DATA.axes.map(axis => {
      const mass = DATA.questions.reduce(
        (sum, question) => sum + Math.abs(question.coefficients[axis.key] || 0),
        0
      );
      const numerator = DATA.questions.reduce(
        (sum, question, index) =>
          sum + (entity.responses[index] ?? 0) * (question.coefficients[axis.key] || 0),
        0
      );
      return [axis.key, mass ? 10 * numerator / (3 * mass) : 0];
    }));

    entity.averageConfidence = entity.confidence.reduce(
      (sum, value) => sum + (Number(value) || 0),
      0
    ) / entity.confidence.length;
  });
